const guard=$json;
const input=$('Receive Win Gate Context').item.json;

if(!guard.allowed){
  return {json:{
    status:guard.nextAction==='human_required'?'human_required':'blocked',
    operations:[],
    guard,
    blockers:[guard.reasonCode]
  }};
}

const eventId=input.customer_event_id;
const operations=[{
  action:'TRANSITION_CUSTOMER_EVENT',
  customer_event_id:eventId,
  from_stage:'FECHAMENTO',
  to_stage:'GANHO',
  expected_version:input.stage_version,
  reason_code:'SIGNED_AND_VERIFIED_PAYMENT'
}];

if(input.reservation?.status!=='confirmed'){
  operations.push({
    action:'UPSERT_RESERVATION',
    idempotency_key:'reservation:'+String(eventId),
    customer_event_id:eventId,
    status:'confirmed',
    source:'win_gate',
    reason_code:'SIGNED_AND_VERIFIED_PAYMENT'
  });
}

operations.push({
  action:'UPSERT_LOGISTICS_RECORD',
  idempotency_key:'logistics-record:'+String(eventId),
  customer_event_id:eventId,
  status:'pending'
});

if(!input.logistics_projection?.card_id){
  operations.push({
    action:'UPSERT_LOGISTICS_PROJECTION',
    idempotency_key:'trello:logistics:'+String(eventId),
    customer_event_id:eventId,
    board_name:'3.1 - LOGISTICA',
    target_list_name:'CONTRATOS EM ANDAMENTO',
    preserve_existing_structure:true,
    move_other_lists:false
  });
}

if((input.operational_stage ?? 'NOT_STARTED')==='NOT_STARTED'){
  operations.push({
    action:'TRANSITION_OPERATIONAL_STAGE',
    customer_event_id:eventId,
    from_stage:'NOT_STARTED',
    to_stage:'PRE_EVENT',
    requires_commercial_stage:'GANHO'
  });
}

operations.push({
  action:'EMIT_EVENT',
  event_type:'event_won',
  customer_event_id:eventId,
  idempotency_key:'event-won:'+String(eventId)
});

return {json:{
  status:'planned',
  guard,
  operations,
  reservation_confirmed:true,
  logistics_board_structure_change:false,
  blockers:[]
}};
